"""Create 20 original puzzle assets + a PRIVATE organizer answer key.

Requires Pillow only when generating images; the competition server itself uses
only Python's standard library. Never commit the generated organizer folder.
"""
from __future__ import annotations
import argparse, base64, codecs, hashlib, io, json, math, random, secrets, struct, wave, zipfile
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont, PngImagePlugin

ROOT=Path(__file__).resolve().parents[1]
WORDS=['EMBER','CIPHER','NOVA','VECTOR','ORBIT','PIXEL','SHADOW','SIGNAL','NEBULA','MIRROR','DELTA','KERNEL']
MORSE={**dict(zip('ABCDEFGHIJKLMNOPQRSTUVWXYZ',['.-','-...','-.-.','-..','.','..-.','--.','....','..','.---','-.-','.-..','--','-.','---','.--.','--.-','.-.','...','-','..-','...-','.--','-..-','-.--','--..'])),**dict(zip('0123456789',['-----','.----','..---','...--','....-','.....','-....','--...','---..','----.']))}

def fresh(label):return f'HUNT{{{label}_{secrets.token_hex(4).upper()}}}'
def image_canvas(w=620,h=330,tone=0):
 im=Image.new('RGB',(w,h));px=im.load()
 for y in range(h):
  for x in range(w):
   px[x,y]=(int(13+20*x/w+8*math.sin((y+x*0.2)/60))%256,int(23+31*y/h+7*math.cos(x/55))%256,int(43+55*x/w+18*math.sin(y/90+tone))%256)
 d=ImageDraw.Draw(im)
 for i in range(5):d.rectangle((28+i*15,40+i*19,w-30-i*19,h-30-i*16),outline=(39+i*9,75+i*11,93+i*12),width=2)
 d.ellipse((w-155,40,w-65,130),outline=(79,192,180),width=3)
 d.line((0,h-63,w,h-63),fill=(69,163,158),width=2)
 d.text((28,h-40),'CCH  /  EVIDENCE ARCHIVE',fill=(129,221,206))
 return im

def png_save(im,path,metadata=None):
 info=PngImagePlugin.PngInfo()
 for k,v in (metadata or {}).items():info.add_text(k,v)
 im.save(path,pnginfo=info)

def bits(data):
 for byte in data:
  for n in range(7,-1,-1):yield (byte>>n)&1

def embed_bits(im,data,channel=0,seed=0):
 raw=bytearray(im.tobytes()); stream=struct.pack('>H',len(data))+data
 for i,b in enumerate(bits(stream)):
  index=i*len(im.getbands())+channel
  if index>=len(raw):raise ValueError('Image is too small')
  raw[index]=(raw[index]&254)|b
 return Image.frombytes(im.mode,im.size,bytes(raw))

def wav_base(duration=4.0,rate=22050):
 n=int(duration*rate);return [int(12000*math.sin(2*math.pi*440*i/rate)+3000*math.sin(2*math.pi*97*i/rate)) for i in range(n)]
def write_wav(path,samples,rate=22050):
 with wave.open(str(path),'wb') as w:
  w.setnchannels(1);w.setsampwidth(2);w.setframerate(rate)
  w.writeframes(struct.pack('<'+'h'*len(samples),*samples))

def rail(text,rails):
 tracks=['' for _ in range(rails)];r=0;direction=1
 for ch in text:
  tracks[r]+=ch
  if r==0:direction=1
  elif r==rails-1:direction=-1
  r+=direction
 return ''.join(tracks)

def vig(text,key):
 out='';j=0
 for ch in text:
  if ch.isalpha():out+=chr((ord(ch)-65+ord(key[j%len(key)])-65)%26+65);j+=1
  else:out+=ch
 return out

def caesar(text,offset):return ''.join(chr((ord(c)-65+offset)%26+65) if 'A'<=c<='Z' else c for c in text)

def build(output:Path):
 if (output/'manifest.json').exists():raise SystemExit('Refusing to overwrite an existing answer key. Choose a fresh output folder.')
 assets=output/'assets';assets.mkdir(parents=True,exist_ok=True)
 challenges=[];answers=[]
 def add(slug,title,cat,points,description,hint,filename,flag,solution,mode='static'):
  row={'slug':slug,'title':title,'category':cat,'points':points,'description':description,'hint':hint,'asset_name':filename or '', 'flag_mode':mode,'order':len(challenges)+1}
  if mode=='static':row['flag']=flag
  challenges.append(row)
  answers.append({'number':len(challenges),'title':title,'slug':slug,'flag':flag if mode=='static' else 'Dynamic: unique per participant; generated by server','steps':solution})
 # Steganography (9)
 f=fresh('META');png_save(image_canvas(),assets/'01_station.png',{'Artist':'Archive Team','Comment':'HUNT{FALSE_POSITIVE}','Description':'Archived correction token: '+f})
 add('steg-metadata','The Forgotten Caption','Steganography',100,'The museum stored its first clue in a PNG. The visible pixels are a distraction. Inspect the embedded textual metadata and submit the correction token.','PNG metadata is not the same as visible text. Check textual chunks.','01_station.png',f,'Read PNG text metadata: Description contains the valid token; Comment is a decoy.')
 f=fresh('RED');png_save(embed_bits(image_canvas(tone=2),f.encode(),0),assets/'02_red_channel.png')
 add('steg-red-lsb','The Red Thread','Steganography',100,'A watchtower image carries a message in the least significant bit of its red channel. The first 16 bits encode the message length in bytes (big endian). Extract the remaining bytes as UTF-8.','For pixel zero, take (R & 1). Continue in row-major order.','02_red_channel.png',f,'Read red-channel LSBs in row-major order. First two bytes are a big-endian length; decode following bytes as text.')
 f=fresh('BLUE');im=image_canvas(760,380,tone=4);base=im.copy();layer=Image.new('L',(760,380),0);d=ImageDraw.Draw(layer);d.text((62,155),f,fill=255,stroke_width=1)
 rb=bytearray(im.tobytes());mask=layer.tobytes()
 for i,val in enumerate(mask):rb[i*3+2]=min(255,rb[i*3+2]//4 + (190 if val else 0))
 im=Image.frombytes('RGB',im.size,bytes(rb));png_save(im,assets/'03_blueprint.png')
 add('steg-blue','Blueprint in Blue','Steganography',100,'The archive scanned a faded blueprint. One color plane contains a line of text. Separate the RGB channels, isolate blue, and increase contrast.','Open the blue channel on its own; the other two channels are deliberate noise.','03_blueprint.png',f,'Split RGB image and view the blue channel; read the bright text in its centre.')
 f=fresh('TRAIL');path=assets/'04_after_the_end.png';png_save(image_canvas(tone=1),path)
 with path.open('ab') as stream:stream.write(b'\nARCHIVE PAYLOAD BEGINS\n'+base64.b64encode(f.encode())+b'\nARCHIVE PAYLOAD ENDS\n')
 add('steg-trailer','After the Final Pixel','Steganography',200,'Your image viewer stops at the end of the PNG, but the disk file does not. Search beyond the IEND chunk and decode the archived payload.','Inspect the final bytes of the file with a hex editor or tail; the payload uses a common text encoding.','04_after_the_end.png',f,'Find bytes appended after PNG IEND and Base64-decode the payload.')
 f=fresh('AUDIO');samples=wav_base(5);payload=struct.pack('>H',len(f.encode()))+f.encode()
 for i,b in enumerate(bits(payload)):samples[i]=(samples[i]&~1)|b
 write_wav(assets/'05_carrier.wav',samples)
 add('steg-audio-lsb','A Quiet Bitstream','Steganography',200,'A mono 16-bit WAV recording hides a flag in the least significant bit of each signed audio sample. The first sixteen hidden bits give the byte count (big endian).','Read 16-bit PCM samples, not raw file bytes. Extract sample & 1.','05_carrier.wav',f,'Read PCM samples and use the LSB of each; decode 16-bit length then message bytes.')
 token='MORSE'+secrets.token_hex(3).upper();f=f'HUNT{{{token}}}';samples=[];rate=16000;unit=.085
 def add_tone(sec,on):
  n=int(sec*rate)
  start=len(samples)
  for i in range(n):samples.append(int(13000*math.sin(2*math.pi*720*(start+i)/rate)) if on else 0)
 for j,ch in enumerate(token):
  for k,symbol in enumerate(MORSE[ch]):
   add_tone(unit*(3 if symbol=='-' else 1),True)
   if k!=len(MORSE[ch])-1:add_tone(unit,False)
  if j!=len(token)-1:add_tone(unit*3,False)
 write_wav(assets/'06_beacon.wav',samples,rate)
 add('steg-morse','Beacon at 720 Hz','Steganography',200,'The audio is a transmission of dots and dashes at approximately 720 Hz. Decode the letters and digits, then wrap the resulting word in HUNT{...}.','Short pulse = dot, long pulse = dash. Spaces between characters are longer than spaces between pulses.','06_beacon.wav',f,'Listen to the WAV or view wave amplitude; transcribe Morse and wrap token in HUNT{...}.')
 f=fresh('SCAN');im=image_canvas(620,330,tone=0);stream=struct.pack('>H',len(f.encode()))+f.encode();pix=im.load()
 for i,b in enumerate(stream):pix[i,0]=(b,120,200)
 png_save(im,assets/'07_scanline.png')
 add('steg-scanline','First Row, First Word','Steganography',300,'A calibration image stores one byte per pixel at the very top of the frame. Read only the red value of each top-row pixel, starting with a 2-byte big-endian payload length.','Pixel (0,0) has the first length byte; pixel (1,0) has the second.','07_scanline.png',f,'Read red-channel values from top row; first two are length; next bytes decode the flag.')
 f=fresh('ALPHA');im=image_canvas(620,330).convert('RGBA');im=embed_bits(im,f.encode(),3);bio=io.BytesIO();im.save(bio,format='PNG')
 with zipfile.ZipFile(assets/'08_casefile.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
  z.writestr('case/forensic_note.txt','Ignore the screenshot caption. The real evidence is in the alpha-plane LSBs; 16-bit length prefix, RGB-like row-major order.\n')
  z.writestr('case/do_not_submit.txt','HUNT{THIS_IS_A_DECOY}\n')
  z.writestr('case/trace.png',bio.getvalue())
 add('steg-alpha','The Transparent Witness','Steganography',300,'The ZIP contains a decoy and an RGBA image. Extract the real message from the alpha-channel least significant bits; the first 16 bits are a big-endian payload length.','Use the alpha values, not red/green/blue.','08_casefile.zip',f,'Open case/trace.png as RGBA. Read alpha LSBs, 16-bit length then UTF-8 flag; ignore the decoy.')
 f=fresh('XOR');key=b'ECHO';encrypted=bytes(v^key[i%len(key)] for i,v in enumerate(f.encode()));im=embed_bits(image_canvas(tone=5),encrypted,2)
 png_save(im,assets/'09_whisper.png',{'Cipher':'repeating XOR','Callsign':'ECHO','Comment':'Blue carries the encrypted packet. First 16 hidden bits represent length.'})
 add('steg-xor','Whispers in the Blue','Steganography',450,'The carrier stores an encrypted byte stream in its blue-channel LSBs. The first two bytes give its length. The PNG metadata identifies the cipher and the callsign used as the key.','The key is a four-letter callsign, repeated across bytes.','09_whisper.png',f,'Read blue channel LSBs with 2-byte length, then apply repeated XOR with ECHO (from PNG metadata).')
 # Cryptography (7)
 f=fresh('SHIFT');(assets/'10_shift.txt').write_text('ARCHIVED SHIFTED MESSAGE\n'+caesar(f,7)+'\nShift size: seven positions ahead. Recover the unshifted string.\n')
 add('crypto-caesar','Seven Steps Away','Cryptography',100,'A Caesar shift has moved letters forward by seven. The ciphertext is inside the attached message. Keep punctuation unchanged.','Shift A–Z seven places backward to decrypt.','10_shift.txt',f,'Caesar decrypt shift 7.')
 f=fresh('VIG');(assets/'11_orbit.txt').write_text('KEYWORD = ORBIT\nCIPHERTEXT = '+vig(f,'ORBIT')+'\nNon-alphabetic characters do not advance the key.\n')
 add('crypto-vigenere','Orbital Cipher','Cryptography',100,'A repeating-key Vigenère cipher was used. The keyword appears in the intercepted message. Only letters consume key positions.','The key is ORBIT. Keep braces and underscores untouched.','11_orbit.txt',f,'Vigenère decrypt with ORBIT (letters advance key).')
 f=fresh('SUB');plain='ABCDEFGHIJKLMNOPQRSTUVWXYZ';sub='QWERTYUIOPASDFGHJKLZXCVBNM';cipher=''.join(sub[plain.index(ch)] if ch in plain else ch for ch in f)
 (assets/'12_monoalphabet.txt').write_text(f'PLAIN : {plain}\nCIPHER: {sub}\n\nINTERCEPTED: {cipher}\n')
 add('crypto-substitution','The Keyboard Alphabet','Cryptography',200,'The alphabet was substituted according to a published mapping. Use the provided plain/cipher table to reverse it.','Match each letter of CIPHER back to the letter in PLAIN at the same index.','12_monoalphabet.txt',f,'Apply inverse monoalphabetic substitution table.')
 f=fresh('RAIL');(assets/'13_rails.txt').write_text('ROUTES = 3\nTRANSPOSED = '+rail(f,3)+'\nRails zigzag down and back up.\n')
 add('crypto-rail','Three Parallel Tracks','Cryptography',200,'A rail-fence transposition used three tracks. Read the attached intercepted token, then reverse the zigzag arrangement.','Draw three rows and trace a zigzag to place the plaintext letters.','13_rails.txt',f,'Rail fence decrypt at depth 3.')
 f=fresh('XOR');key=b'ICE';blob=bytes(v^key[i%3] for i,v in enumerate(f.encode()))
 (assets/'14_frozen_hex.txt').write_text('RECOVERED HEX STREAM\n'+blob.hex().upper()+'\nCLUE: frozen water, three letters. Repeat the clue as a byte key.\n')
 add('crypto-xor','The Frozen Hex','Cryptography',300,'The file contains hexadecimal bytes that were encrypted using repeating-key XOR. The three-character key is described by the clue.','Frozen water = ICE. Convert hex to bytes; XOR with I, C, E repeatedly.','14_frozen_hex.txt',f,'Hex decode, repeating XOR key ICE.')
 f=fresh('RSA');p=1009;q=1013;n=p*q;e=17
 cipher=' '.join(str(pow(ord(ch),e,n)) for ch in f)
 (assets/'15_rsa.txt').write_text(f'PUBLIC KEY n = {n}\nPUBLIC EXPONENT e = {e}\nENCRYPTED ASCII CODEPOINTS (one byte per block):\n{cipher}\n\nThis is intentionally tiny, insecure textbook RSA. No padding.\n')
 add('crypto-small-rsa','Tiny Keys, Big Mistake','Cryptography',450,'A classroom demonstration used textbook RSA with a very small modulus. Factor n, calculate the private exponent, decrypt each integer and interpret it as ASCII.','n can be factored by trial division. Compute phi=(p-1)(q-1); d=e^-1 mod phi.','15_rsa.txt',f,'Factor n=1009×1013, compute modular inverse of 17 mod phi, pow(each block,d,n), decode ASCII.')
 f=fresh('LAYERS');payload=codecs.encode(f,'rot_13').encode();encoded=base64.b64encode(payload).hex()
 (assets/'16_layers.txt').write_text('CIPHER TRANSCRIPT\n'+encoded+'\n\nRoute of original encryption: ROT13 -> Base64 -> hexadecimal. Reverse the route.\n')
 add('crypto-layers','Three Locks, One Key','Cryptography',300,'Three encodings were applied in succession: ROT13, Base64, then hexadecimal. Reverse all layers to recover the original flag.','Decode hex first, then Base64, then ROT13.','16_layers.txt',f,'Hex decode, Base64 decode, ROT13.')
 # Web Security: dynamic personal flags
 add('web-source','The Invisible Source','Web Security',100,'Visit /arena/source while logged in. The page shows no clue, but its actual HTML response carries a hidden message. Find the flag and submit it.','Use View Page Source (Ctrl+U) or inspect the HTML document, not just Elements.','',None,'Visit /arena/source; view HTML comment.',mode='dynamic')
 add('web-headers','The Courier Header','Web Security',200,'Visit /arena/headers while logged in. The response headers carry a custom field. Use browser developer tools (Network tab) or curl with session cookies to inspect the response.','Look for a header beginning with X-Courier.','',None,'Inspect HTTP response header X-Courier-Token.',mode='dynamic')
 add('web-vault','The Badge That Lied','Web Security',300,'Visit /arena/vault. A demo access-control page trusts a badge specified by the client. Discover which badge value unlocks the simulated protected message. This is an intentionally isolated teaching exercise, not a real admin portal.','Compare /arena/vault?badge=guest with a hypothetical auditor badge.','',None,'Request /arena/vault?badge=auditor.',mode='dynamic')
 # Final: private challenge-specific passphrase, not embedded in the app source
 w1,w2=random.sample(WORDS,2);number=secrets.randbelow(90)+10;phrase=f'{w1}:{w2}:{number}'
 finalimg=image_canvas(tone=6);finbio=io.BytesIO();finalinfo=PngImagePlugin.PngInfo();finalinfo.add_text('First-fragment',w1);finalimg.save(finbio,format='PNG',pnginfo=finalinfo)
 with zipfile.ZipFile(assets/'20_final_hunt.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
  z.writestr('01-visual.png',finbio.getvalue())
  z.writestr('02-radio.txt','The second word is ROT13 encoded: '+codecs.encode(w2,'rot_13')+'\n')
  z.writestr('03-terminal.txt',f'Last fragment: {number:08b} (binary).\n')
  z.writestr('README.txt','Combine first-fragment, decoded second word, and binary number. Format WORD:WORD:NUMBER. Submit at /arena/finale?phrase=YOUR-PHRASE to receive your personal final flag.\n')
 add('final-hunt','The Final Evidence Vault','Final Hunt',750,'Three independent traces were recovered: an image, an intercepted radio note, and a binary terminal log. Solve each, join the fragments as WORD:WORD:NUMBER, then submit the phrase at /arena/finale. The endpoint returns your personal final flag.','The PNG has textual metadata. ROT13 is reversible. Eight binary digits are a decimal number.','20_final_hunt.zip',None,'Read PNG text fragment; ROT13 the second word; convert third byte from binary; join as '+phrase+' and access /arena/finale?phrase='+phrase+'.',mode='dynamic')
 assert len(challenges)==20
 assert [sum(c['category']==cat for c in challenges) for cat in ('Steganography','Cryptography','Web Security','Final Hunt')]==[9,7,3,1]
 manifest={'format':1,'title':'Crypto Cyber Hunt','generated_utc':'generated offline','final_phrase':phrase,'challenges':challenges}
 (output/'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
 lines=['CRYPTO CYBER HUNT — ORGANIZER ANSWER KEY','PRIVATE: NEVER PUBLISH THIS FILE OR THE MANIFEST','',f'Final vault passphrase: {phrase}','']
 for a in answers:lines.extend([f"{a['number']:02d}. {a['title']} ({a['slug']})",f"Flag: {a['flag']}",f"Solution: {a['steps']}",''])
 (output/'ORGANIZER_ANSWER_KEY.txt').write_text('\n'.join(lines),encoding='utf8')
 (output/'README_PRIVATE.txt').write_text('PRIVATE COMPETITION PACK\n\nDo not commit or share this folder. Run: python app.py import-pack <this-folder>\nThen run admin UI to publish/start the competition.\nAll 20 challenges, evidence files and their validation records are in manifest.json and assets/.\nWeb and final flags are generated uniquely per signed-in participant.\n',encoding='utf8')
 print(f'Generated {len(challenges)} challenges in {output} ({len(list(assets.iterdir()))} file artifacts).')

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('output',type=Path);build(p.parse_args().output)